    UserManager<IdentityUser> um,
    SignInManager<IdentityUser> sm) : ControllerBase
{
    [HttpPost("register")]
    public async Task<IActionResult> Register(string email, string pwd)
    {
        var user = new IdentityUser { UserName = email, Email = email };
        var r = await um.CreateAsync(user, pwd);   // 哈希存库
        return r.Succeeded ? Ok() : BadRequest(r.Errors);
    }

    [HttpPost("login")]
    public async Task<IActionResult> Login(string email, string pwd)
    {
        var user = await um.FindByEmailAsync(email);
        if (user is null ||
            !await um.CheckPasswordAsync(user, pwd)) return Unauthorized();
        await sm.SignInAsync(user, isPersistent: true); // 发 Cookie
        return Ok();
    }
}

