// 待办服务 + 控制器(组合 asp11/asp15)
public class TodoService(AppDbContext db)
{
    public async Task<List<Todo>> Mine(string userId)
        => await db.Todos.Where(t => t.OwnerId == userId)
                         .OrderByDescending(t => t.CreatedAt).ToListAsync();

    public async Task<Todo?> Get(string userId, int id)
        => await db.Todos.FirstOrDefaultAsync(t =>
            t.Id == id && t.OwnerId == userId);
}

// 控制器只做 HTTP 层, 组合认证+属主
[Authorize]
[ApiController]
[Route("api/[controller]")]
public class TodosController(TodoService svc) : ControllerBase
{
    [HttpGet]
    public Task<List<Todo>> Mine()
        => svc.Mine(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
